def test_search_is_tenant_scoped_and_leaks_nothing() -> None:
    _new_order("q70", 100, tenant="t-search")
    _new_order("q71", 100, tenant="t-other")
    mine = _all_pages(headers=HEADERS)
    assert "q71" not in {o["order_id"] for o in mine}
