def test_pagination_stays_stable_under_inserts_and_book_changes() -> None:
    for i in range(7):
        _new_order(f"q8{i}", 100)

    # 第 1 页
    resp = _search({"page_size": 3})
    page1 = [o["order_id"] for o in resp.json()["orders"]]
    assert page1 == ["q80", "q81", "q82"]
    token = resp.json()["continuation_token"]
    assert token

    # 翻页过程中：新增排序键靠后的订单、把后续页订单结清、把后续页订单金额相关账面变更
    _new_order("q89", 100)  # 排序键在游标之后，后续页应能取到
    assert _pay("q83", 100).status_code == 200  # 后续页订单状态变更，位置不漂移
    _new_order("q7z", 100)  # 排序键在游标之前的新单，不影响本次续取的不重不漏

    seen = set(page1)
    while token:
        body = _search({"page_size": 3, "continuation_token": token}).json()
        for o in body["orders"]:
            assert o["order_id"] not in seen
            seen.add(o["order_id"])
        token = body["continuation_token"]

    # 翻页开始时就存在且排序键在游标之后的订单全部取到，无重复无遗漏
    assert {"q83", "q84", "q85", "q86"} <= seen
    # 翻页期间新增的靠后订单也被取到
    assert "q89" in seen
    # 已返回过的订单没有重复出现（q80..q82 各只出现一次）
    assert seen.isdisjoint(set())  # 占位：真正的不重断言已在循环内逐页完成
    # 账面变更已反映到快照（q83 已结清）
    q83 = _search({"status": "settled"}).json()["orders"]
    assert any(o["order_id"] == "q83" and o["paid_cents"] == 100 and o["outstanding_cents"] == 0 for o in q83)


def test_continuation_token_is_opaque_and_resumable() -> None:
    for i in range(4):
        _new_order(f"q9{i}", 100)
    first = _search({"page_size": 2}).json()
    assert len(first["orders"]) == 2 and first["continuation_token"]
    # 同一令牌重放：返回同一第二页，第一页的订单不会重复
    for _ in range(2):
        second = _search({"page_size": 2, "continuation_token": first["continuation_token"]}).json()
        assert [o["order_id"] for o in second["orders"]] == ["q92", "q93"]
        assert second["continuation_token"] == ""


